// Selection-to-source (phase 2): `rangeFromSelection` maps a highlighted span of the rendered
// preview to a source range, character-precise at both ends via the phase 1 aligner.
//
// The corpus is the phase 1 fixtures (synthetic documents, runs generated by the project's own
// typst.ts) plus <name>.selections.json: hand-labelled selections. A label names the start and
// end as [page, run, text], where `text` is a substring of the run: the start sits at its
// first character, the end after its last one, so the labels read like what a person
// highlights and stay valid if a run is re-split. `line` is where the range must lie, `src` (when
// present) the exact source text it must cover, `approx` whether the result must be flagged
// approximate (generated text), and `swap` hands the ends over in reverse (a backwards drag).

import { describe, it, expect } from 'vitest';
import { readFileSync, readdirSync, existsSync } from 'node:fs';
import { resolve } from 'node:path';
import {
  rangeFromSelection,
  projectSource,
  type SelectionEnd,
  type SelectionRange,
} from '@/lib/typst-source-map';

const DIR = resolve(__dirname, 'fixtures/source-map');

type Anchor = [number, number, string | number];
interface SelLabel { s: Anchor; e: Anchor; line: number | [number, number]; src?: string; approx?: boolean; swap?: boolean; why: string }
interface Fixture { name: string; source: string; pages: string[][]; sels: SelLabel[]; runCount: number }

const fixtures: Fixture[] = readdirSync(DIR)
  .filter((f) => f.endsWith('.typ'))
  .sort()
  .map((f) => {
    const name = f.replace(/\.typ$/, '');
    const pages = (JSON.parse(readFileSync(resolve(DIR, `${name}.runs.json`), 'utf8')) as { pages: string[][] }).pages;
    const selPath = resolve(DIR, `${name}.selections.json`);
    return {
      name,
      source: readFileSync(resolve(DIR, f), 'utf8'),
      pages,
      sels: existsSync(selPath) ? (JSON.parse(readFileSync(selPath, 'utf8')) as SelLabel[]) : [],
      runCount: pages.reduce((n, p) => n + p.length, 0),
    };
  });

function endAt(fx: Pick<Fixture, 'pages'>, p: number, r: number, offset: number): SelectionEnd {
  return { target: { page: p, run: r, pageCount: fx.pages.length, runsOf: (i) => fx.pages[i] ?? [] }, offset };
}

/** The offset a label's anchor stands for: the start of its text, or just after it for an end. */
function offsetOf(fx: Fixture, a: Anchor, side: 'start' | 'end'): number {
  if (typeof a[2] === 'number') return a[2];
  const run = fx.pages[a[0]]![a[1]]!;
  const at = run.indexOf(a[2]);
  if (at === -1) throw new Error(`${fx.name} ${a[0]}:${a[1]} has no ${JSON.stringify(a[2])} in ${JSON.stringify(run)}`);
  return side === 'start' ? at : at + a[2].length;
}

function run(fx: Fixture, l: SelLabel): SelectionRange | null {
  const s = endAt(fx, l.s[0], l.s[1], offsetOf(fx, l.s, 'start'));
  const e = endAt(fx, l.e[0], l.e[1], offsetOf(fx, l.e, 'end'));
  return l.swap ? rangeFromSelection(fx.source, e, s) : rangeFromSelection(fx.source, s, e);
}

const lineOf = (source: string, offset: number) => source.slice(0, offset).split('\n').length;

function onLines(source: string, r: SelectionRange | null, line: SelLabel['line']): boolean {
  if (!r) return false;
  const [lo, hi] = typeof line === 'number' ? [line, line] : line;
  return lineOf(source, r.from) >= lo && lineOf(source, Math.max(r.from, r.to - 1)) <= hi;
}

/** The characters the labelled selection covers in the rendered runs (what the size bound is measured against). */
function renderedLength(fx: Fixture, l: SelLabel): number {
  const flat: Array<{ p: number; r: number }> = [];
  fx.pages.forEach((runs, p) => runs.forEach((_, r) => flat.push({ p, r })));
  const at = (a: Anchor) => flat.findIndex((x) => x.p === a[0] && x.r === a[1]);
  const i = at(l.s), j = at(l.e);
  let n = 0;
  for (let k = i; k <= j; k++) {
    const t = fx.pages[flat[k]!.p]![flat[k]!.r]!;
    const from = k === i ? offsetOf(fx, l.s, 'start') : 0;
    const to = k === j ? offsetOf(fx, l.e, 'end') : t.length;
    n += Math.max(0, to - from) + 1;
  }
  return n;
}
const bound = (len: number) => 3 * len + 200;

describe('selection-to-source corpus', () => {
  it('labels name real runs and substrings (fixtures and labels are in step)', () => {
    let total = 0;
    for (const f of fixtures) {
      for (const l of f.sels) {
        total++;
        offsetOf(f, l.s, 'start'); // throws on a stale label
        offsetOf(f, l.e, 'end');
      }
    }
    expect(total).toBeGreaterThanOrEqual(35);
  });

  it('maps hand-labelled selections to the right lines, exactly where the text is literal, and never returns a huge block', () => {
    const rows: Array<{ fixture: string; n: number; lines: number; exactOf: number; exact: number; approxOf: number; approx: number; clean: number; cleanOf: number }> = [];
    const misses: string[] = [];
    const t = { n: 0, lines: 0, exactOf: 0, exact: 0, approxOf: 0, approx: 0, clean: 0, cleanOf: 0 };
    for (const f of fixtures) {
      if (f.sels.length === 0) continue;
      const row = { fixture: f.name, n: 0, lines: 0, exactOf: 0, exact: 0, approxOf: 0, approx: 0, clean: 0, cleanOf: 0 };
      for (const l of f.sels) {
        const r = run(f, l);
        row.n++;
        const lineHit = onLines(f.source, r, l.line);
        if (lineHit) row.lines++;
        if (l.src !== undefined) {
          row.exactOf++;
          if (r && f.source.slice(r.from, r.to) === l.src) row.exact++;
        }
        if (l.approx) { row.approxOf++; if (r?.approximate) row.approx++; }
        else { row.cleanOf++; if (r && !r.approximate) row.clean++; }
        if (r) expect(r.to - r.from, `${f.name} ${l.why}`).toBeLessThanOrEqual(bound(renderedLength(f, l)));
        const wantSrc = l.src !== undefined && !(r && f.source.slice(r.from, r.to) === l.src);
        if (!lineHit || wantSrc || (l.approx ? !r?.approximate : !!r?.approximate)) {
          misses.push(`${f.name} [${l.why}] want line ${JSON.stringify(l.line)}${l.src !== undefined ? ` src ${JSON.stringify(l.src.slice(0, 50))}` : ''}${l.approx ? ' approx' : ''}; got ${r ? `line ${lineOf(f.source, r.from)}-${lineOf(f.source, Math.max(r.from, r.to - 1))} ${JSON.stringify(f.source.slice(r.from, r.to).slice(0, 60))}${r.approximate ? ' approx' : ''}` : 'nothing'}`);
        }
      }
      rows.push(row);
      for (const k of Object.keys(t) as Array<keyof typeof t>) t[k] += row[k];
    }
    const pct = (a: number, b: number) => (b === 0 ? '  n/a' : `${((a / b) * 100).toFixed(1)}%`);
    const cell = (a: number, b: number) => `${a}/${b} (${pct(a, b)})`.padEnd(15);
    const table = [
      'fixture            sels   on the right lines   exact source text   flagged approx   not flagged (exact cases)',
      ...rows.map((r) => `${r.fixture.padEnd(18)} ${String(r.n).padStart(4)}   ${cell(r.lines, r.n)}      ${cell(r.exact, r.exactOf)}    ${cell(r.approx, r.approxOf)}  ${cell(r.clean, r.cleanOf)}`),
      `${'OVERALL'.padEnd(18)} ${String(t.n).padStart(4)}   ${cell(t.lines, t.n)}      ${cell(t.exact, t.exactOf)}    ${cell(t.approx, t.approxOf)}  ${cell(t.clean, t.cleanOf)}`,
    ].join('\n');
    // Printed on purpose: this is the measured selection hit rate the research doc quotes.
    console.log(`\nselection-to-source hit rate\n${table}\n\nmisses:\n${misses.join('\n')}\n`);

    expect(t.lines / t.n).toBeGreaterThanOrEqual(0.9);
    expect(t.exact / t.exactOf).toBeGreaterThanOrEqual(0.85);
    expect(t.approx).toBe(t.approxOf); // generated text is never reported as exact
    expect(t.clean / t.cleanOf).toBeGreaterThanOrEqual(0.9);
  });
});

describe('selection sanity checks', () => {
  const lab = fixtures.find((f) => f.name === 'lab-report')!;
  const prose = fixtures.find((f) => f.name === 'prose-quotes')!;

  it('swaps a reversed span inside one run, and does not call it approximate', () => {
    const a = endAt(lab, 0, 14, lab.pages[0]![14]!.indexOf('first-order RC'));
    const b = endAt(lab, 0, 14, lab.pages[0]![14]!.indexOf('first-order RC') + 'first-order RC'.length);
    const fwd = rangeFromSelection(lab.source, a, b)!;
    const rev = rangeFromSelection(lab.source, b, a)!;
    expect(rev).toEqual(fwd);
    expect(rev.approximate).toBe(false);
    expect(lab.source.slice(rev.from, rev.to)).toBe('first-order RC');
  });

  it('puts the ends in document order before mapping, so a backwards drag across runs maps like a forward one', () => {
    const l = lab.sels.find((x) => x.why === 'across two runs of a paragraph')!;
    const fwd = run(lab, l);
    const rev = run(lab, { ...l, swap: true });
    expect(rev).toEqual(fwd);
  });

  it('marks an inverted source order approximate and falls back to one end\'s run, never a reversed range', () => {
    // The footnote body renders at the foot of the page but sits mid-paragraph in the source.
    const l = prose.sels.find((x) => x.why.startsWith('to a footnote body'))!;
    const r = run(prose, l)!;
    expect(r.approximate).toBe(true);
    expect(r.to).toBeGreaterThan(r.from);
    const text = prose.source.slice(r.from, r.to);
    // One of the two runs, whole: the plain-text run or the footnote's.
    expect(/Nothing here is final|Both are tracked/.test(text)).toBe(true);
  });

  it('never returns more source than 3x the rendered text plus 200 characters', () => {
    // Two short runs whose matches sit 3000 characters apart: a span like that is a bad match, not a selection.
    const filler = Array.from({ length: 60 }, (_, i) => `Paragraph ${i} talks about something quite unrelated to the matter at hand, at length.`).join('\n\n');
    const source = `Start of the passage is right here.\n\n${filler}\n\nThe passage ends over here at last.\n`;
    const pages = [['Start of the passage is right here.', 'The passage ends over here at last.']];
    const fx = { pages };
    const s = endAt(fx, 0, 0, 0);
    const e = endAt(fx, 0, 1, pages[0]![1]!.length);
    const r = rangeFromSelection(source, s, e)!;
    expect(r).not.toBeNull();
    const len = pages[0]![0]!.length + pages[0]![1]!.length + 2;
    expect(r.approximate).toBe(true);
    expect(r.to - r.from).toBeLessThanOrEqual(3 * len + 200);
  });

  it('returns null for an empty selection and for text that is nowhere in the source', () => {
    const a = endAt(lab, 0, 14, 5);
    expect(rangeFromSelection(lab.source, a, a)).toBeNull();
    const fx = { pages: [['zzzz qqqq xxxx wwww vvvv']] };
    expect(rangeFromSelection(lab.source, endAt(fx, 0, 0, 0), endAt(fx, 0, 0, 10))).toBeNull();
  });

  it('is pure: the projection is shared with click mapping and no second aligner exists', () => {
    expect(projectSource(lab.source)).toBe(projectSource(lab.source));
  });
});

describe('selection mapping performance', () => {
  const largest = [...fixtures].sort((a, b) => b.runCount - a.runCount)[0]!;

  it('maps a selection on the largest fixture in well under the budget (p95)', () => {
    projectSource(largest.source); // paid once per source, like the first click
    const pairs: Array<[{ p: number; r: number }, { p: number; r: number }]> = [];
    largest.pages.forEach((runs, p) => {
      for (let r = 0; r + 2 < runs.length; r += 1) if (runs[r]!.trim().length > 8 && runs[r + 2]!.trim().length > 8) pairs.push([{ p, r }, { p, r: r + 2 }]);
    });
    expect(pairs.length).toBeGreaterThan(50);
    const times: number[] = [];
    // Pass 0 warms the JIT and is not timed: the first samples of a cold process are not what a user waits on.
    for (let pass = 0; pass < 3; pass++) {
      for (const [a, b] of pairs) {
        const s = endAt(largest, a.p, a.r, 2);
        const e = endAt(largest, b.p, b.r, Math.min(6, largest.pages[b.p]![b.r]!.length));
        const t0 = performance.now();
        rangeFromSelection(largest.source, s, e);
        if (pass > 0) times.push(performance.now() - t0);
      }
    }
    times.sort((x, y) => x - y);
    const q = (f: number) => times[Math.min(times.length - 1, Math.floor(times.length * f))]!;
    console.log(`selection time on ${largest.name} (${largest.source.length} source chars, ${largest.runCount} runs, ${times.length} samples): median ${q(0.5).toFixed(2)} ms, p95 ${q(0.95).toFixed(2)} ms, max ${times[times.length - 1]!.toFixed(2)} ms`);
    // p95, not max: under the full parallel suite one GC pause can pass any fixed budget.
    expect(q(0.95)).toBeLessThan(25);
  });
});
